using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.IO.Compression;using System.Windows.Forms;using MP1SkinStudio;
class ReadableProbe
{
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static List<string> results=new List<string>();static string demo,skin,output;
 static T Field<T>(object f,string name){return (T)f.GetType().GetField(name,flags).GetValue(f);}static object Call(object f,string name,params object[] args){try{return f.GetType().GetMethods(flags).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(f,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Test(string name,Action test){test();results.Add("PASS "+name);Console.WriteLine(results.Last());Console.Out.Flush();}
 static StudioForm Open(){var f=new StudioForm(demo);f.LoadProject(skin,"MediaTipOverlay.xml");f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();return f;}
 static bool Drawn(SkinCanvas canvas,SkinControl c){return (bool)Call(canvas,"Drawn",c);}static SkinControl Id(SkinProject p,int id){return p.Controls.Single(c=>SkinProject.ControlId(c)==id);}
 static void Render(StudioForm f,string name){using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(Path.Combine(output,name+".png"));}}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);demo=args[0];skin=args[1];output=args[2];Directory.CreateDirectory(output);Run();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run()
 {
  var original=Directory.GetFiles(skin,"*.xml",SearchOption.AllDirectories).ToDictionary(p=>p,p=>ProjectFile.Digest(File.ReadAllBytes(p)));var assets=Directory.GetFiles(demo,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>ProjectFile.Digest(File.ReadAllBytes(p)));
  Test("MediaTip opens in readable Music layout with one five-line block and unchanged source bindings",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");var s=Field<PreviewState>(f,"state");var canvas=Field<SkinCanvas>(f,"canvas");Check(ReadablePreview.SupportsMediaTip(p)&&Field<ChoiceBox>(f,"previewMode").SelectedIndex==0&&Field<ChoiceBox>(f,"mediaTipScene").Visible,"Readable controls missing");Check(p.Controls.Where(c=>SkinProject.ControlId(c)>=20&&SkinProject.ControlId(c)<=64&&new[]{"label","fadelabel"}.Contains(c.Get("type"))&&Drawn(canvas,c)).Select(c=>SkinProject.ControlId(c).Value).SequenceEqual(new[]{20,21,22,23,24}),"Multiple line blocks drawn");Check(ReadablePreview.Caption(s,Id(p,20)).Contains("Example song.flac")&&Id(p,20).Get("label").Contains("#MediaTip.")&&!p.Dirty&&p.Undo.Count==0,"Sample leaked into XML");Render(f,"Music");}});
  Test("Every MediaTip example switches the rendered block and produces short sample text without XML edits",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");string xml=ProjectFile.XmlSignature(p);var scene=Field<ChoiceBox>(f,"mediaTipScene");var canvas=Field<SkinCanvas>(f,"canvas");var state=Field<PreviewState>(f,"state");for(int i=0;i<5;i++){scene.SelectedIndex=i;Application.DoEvents();var labels=p.Controls.Where(c=>new[]{"label","fadelabel"}.Contains(c.Get("type"))&&Drawn(canvas,c)).ToArray();Check(labels.Length==6&&labels.All(c=>!ReadablePreview.Caption(state,c).Contains("#")),"Unreadable/mixed scene "+i);for(int n=0;n<5;n++)Check(Drawn(canvas,Id(p,(i+2)*10+n)),"Active scene row hidden");Render(f,ReadablePreview.Scenes[i]);}Check(ProjectFile.XmlSignature(p)==xml&&!p.Dirty&&p.Undo.Count==0,"Changing examples edited source");}});
  Test("All layers restores every authored control and raw bindings, then Edit layout restores the sample",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");var mode=Field<ChoiceBox>(f,"previewMode");var canvas=Field<SkinCanvas>(f,"canvas");mode.SelectedIndex=2;Application.DoEvents();Check(p.Controls.All(c=>Drawn(canvas,c))&&!Field<ChoiceBox>(f,"mediaTipScene").Enabled&&Field<Label>(f,"previewModeHint").Text.Contains("Diagnostic"),"Diagnostic scope wrong");Check(ReadablePreview.Caption(Field<PreviewState>(f,"state"),Id(p,21),true).Contains("#MediaTip."),"Raw bindings absent");Render(f,"All-Layers");mode.SelectedIndex=0;Check(!Drawn(canvas,Id(p,31))&&Drawn(canvas,Id(p,21)),"Readable scene not restored");}});
  Test("Selecting a different variant explains isolation and solo draws only that control while keeping raw property input",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");Call(f,"SelectControl",Id(p,31));Check(Field<Label>(f,"previewModeHint").Text.Contains("another variant"),"Hidden variant selection unexplained");string raw=Id(p,31).Get("label");Field<ChoiceBox>(f,"previewMode").SelectedIndex=1;var canvas=Field<SkinCanvas>(f,"canvas");Check(canvas.IsolateSelection&&p.Controls.Count(c=>Drawn(canvas,c))==1&&Drawn(canvas,Id(p,31))&&Field<Dictionary<string,TextBox>>(f,"fields")["label"].Text==raw,"Solo scope/property wrong");Render(f,"Isolated-Video-Title");}});
  Test("View and scene changes preserve pending inputs, XML undo history and source identity",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");Call(f,"SelectControl",Id(p,20));var field=Field<Dictionary<string,TextBox>>(f,"fields")["width"];field.Text="1234";string xml=ProjectFile.XmlSignature(p),key=Field<SkinControl>(f,"selected").Key;Field<ChoiceBox>(f,"mediaTipScene").SelectedIndex=4;Field<ChoiceBox>(f,"previewMode").SelectedIndex=2;Field<ChoiceBox>(f,"previewMode").SelectedIndex=1;Check(field.Text=="1234"&&ProjectFile.XmlSignature(p)==xml&&p.Undo.Count==0&&Field<SkinControl>(f,"selected").Key==key&&(bool)Call(f,"PendingProperties"),"View controls applied/discarded drafts");}});
  Test("View and example save reopen without snapshots, and temporary isolation does not survive page change",()=>
  {using(var f=Open()){Field<ChoiceBox>(f,"mediaTipScene").SelectedIndex=4;Field<ChoiceBox>(f,"previewMode").SelectedIndex=2;string file=Path.Combine(output,"Readable-Radio.mp1skinproj");Call(f,"SaveSession",file);using(var zip=ZipFile.OpenRead(file))Check(zip.Entries.Count==1,"Preview embedded XML changes");Call(f,"ResumeSession",file,null);Check(Field<ChoiceBox>(f,"previewMode").SelectedIndex==2&&Field<ChoiceBox>(f,"mediaTipScene").SelectedIndex==4&&!Field<SkinProject>(f,"project").Dirty,"Saved view not restored");Field<ChoiceBox>(f,"previewMode").SelectedIndex=1;var page=Field<PageListBox>(f,"page");page.SelectedIndex=page.FindStringExact("MediaTip.xml");Application.DoEvents();Check(!Field<SkinCanvas>(f,"canvas").IsolateSelection&&!Field<ChoiceBox>(f,"mediaTipScene").Visible,"Isolation/MediaTip shape leaked to another page");}});
  Test("An actual geometry edit exports the original binding, not sample captions or view settings",()=>
  {using(var f=Open()){var p=Field<SkinProject>(f,"project");var c=Id(p,20);string raw=c.Get("label");p.Edit(c,new Dictionary<string,string>{{"width","1010"}},"Readable acceptance width");Call(f,"RefreshProject",c.Key);Field<ChoiceBox>(f,"mediaTipScene").SelectedIndex=1;string file=Path.Combine(output,"Readable-Edited.mp1skinproj"),zip=Path.Combine(output,"Readable-Edited.zip");Call(f,"SaveSession",file);var restored=ProjectFile.Load(file);restored.Export(zip);using(var archive=ZipFile.OpenRead(zip)){using(var reader=new StreamReader(archive.GetEntry("MediaTipOverlay.xml").Open())){string text=reader.ReadToEnd();Check(text==restored.Sources.Values.Single(s=>s.Changed).Text&&text.Contains(raw)&&!text.Contains("Example song.flac")&&!text.Contains("previewMode"),"Presentation leaked into export");}}restored.UndoChange();Check(!restored.Dirty,"Restored Undo failed");restored.RedoChange();Check(restored.Dirty&&Id(restored,20).Get("width")=="1010","Restored Redo failed");}});
  Test("Generic group isolation includes descendants and excludes unrelated sibling text",()=>
  {using(var f=new StudioForm(demo)){f.LoadProject(demo,"demo.groups.xml");var p=Field<SkinProject>(f,"project");var group=p.Controls.First(c=>c.Get("type")=="group");Call(f,"SelectControl",group);Field<ChoiceBox>(f,"previewMode").SelectedIndex=1;var canvas=Field<SkinCanvas>(f,"canvas");var drawn=p.Controls.Where(c=>Drawn(canvas,c)).ToArray();Check(drawn.Length>1&&drawn.All(c=>ReadablePreview.InSelection(c,group)),"Group solo omitted children or leaked siblings");}});
  Test("Generic unresolved captions shorten in isolated editing while audit still reports uncertainty",()=>
  {using(var f=Open()){f.LoadProject(skin,"myHome.xml");var p=Field<SkinProject>(f,"project");var s=Field<PreviewState>(f,"state");var c=p.Controls.First(x=>new[]{"label","fadelabel"}.Contains(x.Get("type"))&&x.Get("label").Contains("#")&&!(bool)Call(s,"ResolvedLabel",x,x.Get("label")));string raw=c.Get("label");Call(f,"SelectControl",c);Field<ChoiceBox>(f,"previewMode").SelectedIndex=1;Check(!ReadablePreview.Caption(s,c).Contains("#")&&Drawn(Field<SkinCanvas>(f,"canvas"),c)&&Field<Dictionary<string,TextBox>>(f,"fields")["label"].Text==raw&&!(bool)Call(s,"ResolvedLabel",c,raw),"Unknown value was resolved or source replaced");}});
  Test("Example controls remain visible and within bounds at the minimum editor size",()=>
  {using(var f=Open()){f.Size=f.MinimumSize;Application.DoEvents();foreach(var c in new Control[]{Field<ChoiceBox>(f,"previewMode"),Field<ChoiceBox>(f,"mediaTipScene")})Check(c.Visible&&c.Parent.ClientRectangle.Contains(c.Bounds),"Mode/example selector clipped");Render(f,"Minimum");}});
  Check(original.All(p=>ProjectFile.Digest(File.ReadAllBytes(p.Key))==p.Value),"Installed XML changed");Check(assets.All(p=>ProjectFile.Digest(File.ReadAllBytes(p.Key))==p.Value),"Bundled source/assets changed");
  var live=new SkinProject(skin);live.OpenPage("MediaTipOverlay.xml");ProjectFile.Save(live,Path.Combine(output,"MediaTip-Readable.mp1skinproj"));results.Add(results.Count+" passed, 0 failed; "+original.Count+" installed XML and "+assets.Count+" demo hashes unchanged. Synthetic form/selection events; no desktop input.");File.WriteAllLines(Path.Combine(output,"Results.txt"),results);Console.WriteLine(results.Last());
 }
}
